ext('c10_eng_ch13',[
C("💰","अमीर आदमी की तस्वीर",["सोने के सिक्कों से भरे घड़े","बड़ा घर, नौकर-चाकर","फिर भी बेचैनी","हमेशा और पाने की चाह"],"कविता का पात्र एक बहुत अमीर आदमी है। उसके पास सोने के सिक्कों से भरे घड़े हैं। बड़ा घर है, नौकर-चाकर हैं और किसी चीज़ की कमी नहीं। फिर भी वह शांत नहीं है। उसके मन में हमेशा एक ही बात चलती है, और चाहिए, और चाहिए। वह दिन में पैसे गिनता है और रात में उन्हें खोने के डर से जागता है। कवि हमें यह दिखाना चाहते हैं कि सिर्फ़ धन होने से सुख नहीं मिलता। जब तक मन में संतोष नहीं है, तब तक सबसे अमीर आदमी भी भीतर से ग़रीब ही रहता है।"),
C("🕳️","लालच एक गड्ढा है",["लालच कभी नहीं भरता","जितना डालो, उतना ख़ाली","इच्छाएँ बढ़ती जाती हैं","संतोष ही इलाज है"],"कवि ने लालच की तुलना एक गहरे गड्ढे से की है। आप उसमें जितना भी डालते जाइए, वह भरता ही नहीं। लालची आदमी के साथ भी यही होता है। एक लाख मिल जाए, तो उसे दस लाख चाहिए। दस लाख मिल जाए, तो करोड़ चाहिए। इच्छाएँ कभी ख़त्म नहीं होतीं, इसलिए उसका दिल हमेशा ख़ाली रहता है। इस बीमारी का एक ही इलाज है, संतोष। जो इंसान अपने पास की चीज़ों से ख़ुश रहना सीख लेता है, वही सच्चा अमीर कहलाता है।"),
C("🎭","शीर्षक में विरोधाभास",["घर भरा हुआ, दिल ख़ाली","धन बहुत, सुख कम","विरोध से बात गहरी बनती है","शीर्षक पूरी कविता की कुंजी"],"कविता का शीर्षक है द एम्प्टी हार्ट, यानी ख़ाली दिल। ज़रा सोचिए, एक तरफ़ घर सोने से भरा है और दूसरी तरफ़ दिल ख़ाली। यही विरोधाभास कविता की जान है। कवि ने दो विपरीत बातों को साथ रखकर पाठक को चौंकाया है, ताकि वह रुककर सोचे। परीक्षा में अगर पूछा जाए कि शीर्षक कितना उपयुक्त है, तो लिखिए कि यह शीर्षक पूरी कविता का सार बता देता है। धन से तिजोरी भरती है, पर दिल तो प्रेम, संतोष और अपनेपन से भरता है।"),
C("⚖️","संतोष बनाम लालच",["संतोषी कम में भी ख़ुश","लालची ज़्यादा में भी दुखी","संतोष से नींद अच्छी आती है","लालच से रिश्ते बिगड़ते हैं"],"अब संतोष और लालच की तुलना कीजिए। संतोषी आदमी के पास कम हो, तब भी वह ख़ुश रहता है और चैन की नींद सोता है। लालची आदमी के पास बहुत हो, तब भी वह दुखी रहता है और रात भर जागता है। संतोष से रिश्ते मज़बूत होते हैं, क्योंकि आदमी दूसरों के साथ बाँटकर चलता है। लालच से रिश्ते बिगड़ते हैं, क्योंकि आदमी हर चीज़ में अपना फ़ायदा देखता है। कहा भी गया है कि जब आवे संतोष धन, सब धन धूरि समान। यानी संतोष सबसे बड़ा धन है।"),
C("📖","कहावतें और लोक-कथाएँ",["लालच बुरी बला है","राजा मिडास की कहानी","सोने के अंडे वाली मुर्गी","लालच में सब कुछ चला जाता है"],"लालच के बारे में हमारे यहाँ और दुनिया भर में कई कहानियाँ हैं। सोने के अंडे देने वाली मुर्गी की कहानी आपने सुनी होगी, जिसमें लालची मालिक ने एक साथ सारे अंडे पाने के लिए मुर्गी को ही मार दिया। राजा मिडास की कथा भी है, जिसने हर चीज़ को सोना बनाने का वरदान माँगा और अंत में अपना खाना और बेटी भी खो दी। इन सब कहानियों का एक ही सार है, लालच बुरी बला है। यह कविता भी वही बात कहती है, बस कविता के रूप में।"),
C("✍️","पेरियासामी थूरन",["तमिलनाडु के कवि","स्वतंत्रता सेनानी भी","बच्चों के लिए गीत और कहानियाँ","तमिल विश्वकोश के संपादक"],"कवि पेरियासामी थूरन तमिलनाडु के थे। वे सिर्फ़ कवि नहीं, बल्कि देश की आज़ादी के लिए लड़ने वाले सेनानी भी थे। उन्होंने बच्चों के लिए बहुत से गीत और कहानियाँ लिखीं और तमिल भाषा के विश्वकोश के संपादन का बड़ा काम भी किया। यह कविता मूल रूप से तमिल में थी और हम इसे अंग्रेज़ी अनुवाद में पढ़ रहे हैं। यह भी याद रखिए कि हमारे देश के अलग-अलग राज्यों में महान साहित्य है, और अनुवाद की मदद से हम उसे पढ़ सकते हैं।"),
C("🔍","कविता की भाषा और शैली",["सरल और सीधी भाषा","साफ़ नैतिक शिक्षा","तुलना और विरोध का प्रयोग","छोटी पंक्तियाँ, गहरा अर्थ"],"इस कविता की भाषा बहुत सरल है। कठिन शब्द कम हैं, इसलिए कक्षा 10 के विद्यार्थी भी आराम से समझ सकते हैं। कविता सीधे नैतिक शिक्षा देती है, जैसे दादी-नानी की कहावतें देती हैं। कवि ने तुलना और विरोध का सहारा लिया है, जैसे गड्ढा और भरा हुआ घड़ा, धन और ख़ाली दिल। पंक्तियाँ छोटी हैं, पर उनका अर्थ गहरा है। परीक्षा में शैली पर प्रश्न आए, तो इन चार बिंदुओं को लिखिए, सरल भाषा, नैतिक शिक्षा, विरोध और गहरा अर्थ।"),
C("📝","शब्दार्थ दोहराइए",["वेल्थी यानी धनी","ग्रीड यानी लालच","पॉट्स यानी घड़े","कॉइन्स और एम्प्टी"],"आइए नए शब्द दोहराएँ। वेल्थी यानी धनी, ग्रीड यानी लालच, पॉट्स यानी घड़े, कॉइन्स यानी सिक्के, और एम्प्टी यानी ख़ाली। इनके साथ हार्ट यानी दिल, गोल्ड यानी सोना और कंटेंटमेंट यानी संतोष भी याद कर लीजिए। अब हर शब्द से एक वाक्य बनाइए। जैसे ग्रीड इज़ अ बैड हैबिट, यानी लालच बुरी आदत है। और कंटेंटमेंट ब्रिंग्स पीस, यानी संतोष शांति लाता है। ये वाक्य आपकी कॉपी में लिखे हों, तो निबंध और पैराग्राफ़ लिखते समय बहुत काम आएँगे।"),
C("🧩","व्याकरण: कंपेरेटिव",["तुलना के लिए एर जोड़ें","मोर के साथ लंबे शब्द","हैप्पियर, रिचर, पुअरर","दैन से तुलना पूरी होती है"],"आज के व्याकरण में तुलना के रूप याद रखिए। जब दो चीज़ों की तुलना करनी हो, तो छोटे विशेषण में एर जोड़ते हैं। जैसे रिच से रिचर और हैप्पी से हैप्पियर। लंबे विशेषण के पहले मोर लगाते हैं, जैसे मोर डेंजरस। तुलना पूरी करने के लिए दैन आता है। उदाहरण, द फ़ार्मर इज़ हैप्पियर दैन द रिच मैन, यानी किसान अमीर आदमी से ज़्यादा ख़ुश है। यह वाक्य इसी कविता के भाव को भी दिखाता है। पाँच ऐसे वाक्य बनाइए जिनमें दैन का प्रयोग हो।"),
C("🏠","बिहार का उदाहरण",["सादा जीवन, ऊँचे विचार","मेहनत की कमाई में बरकत","दिखावे से बचिए","बाँटकर खाने की परंपरा"],"हमारे बिहार और गाँवों में आज भी यह सीख दी जाती है कि मेहनत की कमाई में बरकत होती है। छठ जैसे त्योहारों में अमीर-ग़रीब सब एक साथ घाट पर खड़े होते हैं और प्रसाद बाँटते हैं। यही भावना हमें लालच से दूर रखती है। आजकल दिखावे की होड़ बहुत बढ़ गई है, जैसे महँगे मोबाइल या कपड़े। पर असली सुख दिखावे में नहीं है। अपनी ज़रूरत के हिसाब से जीना और दूसरों के साथ बाँटना ही सच्ची अमीरी है। यही बात इस कविता का केंद्र है।"),
C("🌱","जीवन में संतोष कैसे लाएँ",["जो है, उसके लिए धन्यवाद कहें","दूसरों से तुलना कम करें","ज़रूरत और इच्छा में फ़र्क़ समझें","थोड़ा दान या सेवा करें"],"संतोष कोई जादू नहीं, यह एक आदत है। पहला तरीक़ा, रोज़ रात सोने से पहले उन तीन चीज़ों को याद कीजिए जिनके लिए आप आभारी हैं। दूसरा, दूसरों से अपनी तुलना कम कीजिए, क्योंकि तुलना से ही असंतोष पैदा होता है। तीसरा, ज़रूरत और इच्छा में फ़र्क़ समझिए। ज़रूरत रोटी है, इच्छा महँगा पिज़्ज़ा। चौथा, थोड़ा दान या सेवा कीजिए। जब आप किसी की मदद करते हैं, तो दिल सचमुच भरा हुआ लगता है। ये आदतें आपको सच्चा अमीर बना देंगी।"),
C("📌","पूरी कविता का सार",["धनी आदमी का ख़ाली दिल","लालच कभी न भरने वाला गड्ढा","अंत में लालच ही उसका नाश","संतोष और प्रेम से दिल भरता है"],"अंत में पूरी कविता का सार याद कर लीजिए। पेरियासामी थूरन की कविता में एक धनी आदमी है, जिसके पास सोने के सिक्कों से भरे घड़े हैं, पर उसका दिल ख़ाली है, क्योंकि लालच का गड्ढा कभी नहीं भरता। अंत में यही लालच उसे बर्बाद कर देता है। कविता हमें सिखाती है कि दिल धन से नहीं, बल्कि संतोष और प्रेम से भरता है। इस सार को पाँच वाक्यों में अपने शब्दों में लिखिए और कल सुबह एक बार दोहराइए।"),
C("❓","संभावित परीक्षा प्रश्न",["कवि कौन हैं और कहाँ के","अमीर आदमी के पास क्या था","उसका दिल ख़ाली क्यों था","कविता का संदेश बताइए"],"अब परीक्षा के प्रश्न देखिए। पहला, कवि कौन हैं? उत्तर, पेरियासामी थूरन, तमिलनाडु के। दूसरा, अमीर आदमी के पास क्या था? उत्तर, सोने के सिक्कों से भरे घड़े। तीसरा, उसका दिल ख़ाली क्यों था? उत्तर, क्योंकि उसे और पाने का लालच था और संतोष नहीं था। चौथा, संदेश? उत्तर, लालच विनाश की ओर ले जाता है, और सच्ची ख़ुशी संतोष तथा प्रेम में है। उत्तर लिखते समय पूरे वाक्य बनाइए और कारण ज़रूर लिखिए।"),
Q("आपके हिसाब से असली अमीर कौन होता है और क्यों?","जो संतुष्ट और ख़ुश रहता है और दूसरों की मदद करता है, क्योंकि सच्चा सुख धन से नहीं, संतोष से मिलता है।","अब आपके लिए एक सोचने वाला प्रश्न। आपके हिसाब से असली अमीर कौन होता है और क्यों? कुछ पल सोचिए। ... असली अमीर वह है जो संतुष्ट और ख़ुश रहता है और दूसरों की मदद करता है, क्योंकि सच्चा सुख धन से नहीं, संतोष से मिलता है। अपना उत्तर कारण के साथ लिखिए।"),
],7)
